const b = $('Webhook').item.json.body;
const issue = b.issue;
const body = issue.body || '';
const assignees = (issue.assignees || []).map(a => a.login);
const args = {
  surface: 'issue-action',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  issueNumber: issue.number,
  issueTitle: issue.title,
  issueBody: body,
  issueUrl: issue.html_url,
  assigneeLogin: assignees[0] || '',
  reviewerLogin: '',
  title: issue.title,
  bodyText: body,
};
const prompt = `Issue #${args.issueNumber}: ${args.issueTitle}

${args.issueBody}

Implement a fix. Keep the change minimal and focused on the reported problem. Commit with a clear message and exit when done.
`;
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
